package com.adent.clinical.api;
import com.adent.clinical.domain.ClinicalForm; import com.adent.clinical.repository.ClinicalFormRepository; import com.adent.patient.repository.PatientRepository; import com.adent.shared.exception.NotFoundException; import com.adent.shared.security.CurrentUser; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.OffsetDateTime; import java.util.*;
@RestController @RequestMapping("/api/clinical/forms") @PreAuthorize("hasAnyRole('OWNER','DENTIST','DENTAL_ASSISTANT')")
public class ClinicalFormController {
 private final CurrentUser current; private final ClinicalFormRepository repo; private final PatientRepository patients;
 public ClinicalFormController(CurrentUser c,ClinicalFormRepository r,PatientRepository p){current=c;repo=r;patients=p;}
 @GetMapping("/patient/{patientId}") public List<ClinicalForm> list(@PathVariable UUID patientId){patients.findByIdAndTenantId(patientId,current.tenantId()).orElseThrow(()->new NotFoundException("Paciente no encontrado"));return repo.findByTenantIdAndPatientIdOrderByRecordedAtDesc(current.tenantId(),patientId);}
 @GetMapping("/patient/{patientId}/{type}") public ClinicalForm latest(@PathVariable UUID patientId,@PathVariable String type){return repo.findFirstByTenantIdAndPatientIdAndFormTypeOrderByRecordedAtDesc(current.tenantId(),patientId,type.toUpperCase()).orElse(null);}
 @PostMapping @PreAuthorize("hasAnyRole('DENTIST','DENTAL_ASSISTANT')") public ClinicalForm save(@RequestBody FormRequest r){patients.findByIdAndTenantId(r.patientId(),current.tenantId()).orElseThrow(()->new NotFoundException("Paciente no encontrado"));ClinicalForm f=new ClinicalForm();f.setTenantId(current.tenantId());f.setPatientId(r.patientId());f.setEncounterId(r.encounterId());f.setFormType(r.formType().toUpperCase());f.setDataJson(r.dataJson()==null?"{}":r.dataJson());f.setStatus(r.status()==null?"DRAFT":r.status());f.setRecordedBy(current.username());f.setRecordedAt(OffsetDateTime.now());return repo.save(f);} public record FormRequest(UUID patientId,UUID encounterId,String formType,String dataJson,String status){}
}
